 static async Task Run(){var plugin=new ImageAcquisitionPlugin();var registry=new ModuleRegistry();var host=new ToolPluginRegistry();host.Register(plugin,registry);Check(host.Find(ImageAcquisitionPlugin.Id)==plugin,"registration");Check(plugin.Descriptor.Outputs.Count==54,"flattened output declaration");var p=plugin.Descriptor.Parameters.ToDictionary(d=>d.Name,d=>d.DefaultValue!.Value.Clone());Check(p["ImageSourceType"].GetInt32()==2&&p["Interval"].GetInt32()==1000,"native defaults");string root=Path.GetFullPath("analysis/full-audit/image-acquisition/checks/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var paths=Enumerable.Range(0,9).Select(i=>Path.Combine(root,i+".bmp")).ToArray();for(int i=0;i<9;i++)Fixture(paths[i],10+20*i);using var scope=new ModuleExecutionScope();
  ValueTask<ModuleResult> Execute(CancellationToken token=default)=>registry.Create(plugin.Manifest.Id,"1.0.0").ExecuteAsync(new("test",root,new Dictionary<string,PortValue>(),p){Scope=scope},token);
  Check((await Execute()).NativeErrorCode==0xe0000001,"unbound camera");Set(p,"ImageSourceType",1);Check((await Execute()).NativeErrorCode==0xe0000203,"local empty");Set(p,"ImagePaths",JsonSerializer.Serialize(paths));int cursor=0;foreach(int count in new[]{4,4,4,3,8,8,8,4}){Set(p,"ImageCount",count);var result=await Execute();Check(result.Status==ModuleStatus.Success&&result.Outputs["ImageCount"].As<long>()==count,"count");for(int i=0;i<count;i++){var image=result.Outputs[$"OutImage{i}Image"].As<IImageData>();Check(image.Width==8&&image.Height==8&&image.Pixels.ToArray().All(b=>b==10+20*((cursor+i)%9)),"native sequence and all pixels");}cursor=(cursor+count)%9;Check(!result.Outputs.ContainsKey($"OutImage{count}Image"),"no stale slots");}
  Set(p,"ImageCount",2);Check((await Execute()).ErrorCode=="InvalidParameter","count lower bound");Set(p,"ImageCount",4);var cfg=new[]{new AcquisitionImageConfig(Distribution:0),new AcquisitionImageConfig(Distribution:45.123456,Irradiation:10.123456)};Set(p,"ImageConfigList",JsonSerializer.Serialize(cfg));var angles=await Execute();Check(angles.Outputs["OutImage1Distribution"].As<double>()==(float)45.123456,"distribution float32");Check(angles.Outputs["OutImage1Irradiation"].As<double>()==(float)10.123456,"irradiation float32");
  Set(p,"ImagePaths",JsonSerializer.Serialize(paths.Take(2)));File.Delete(paths[1]);var missing=await Execute();Check(missing.NativeErrorCode==0xe0000201&&missing.Outputs.ContainsKey("OutImage0Image")&&!missing.Outputs.ContainsKey("OutImage1Image"),"partial output missing second");var retry=await Execute();Check(retry.NativeErrorCode==0xe0000201&&!retry.Outputs.ContainsKey("OutImage0Image"),"failed cursor retained");Fixture(paths[1],30);Check((await Execute()).Status==ModuleStatus.Success,"recover missing");
