 static IEnumerable<DependencyObject> Descendants(DependencyObject root){for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);yield return child;foreach(var x in Descendants(child))yield return x;}}
 static void Ui(){var plugin=new ImageAcquisitionPlugin();var p=plugin.Descriptor.Parameters.ToDictionary(d=>d.Name,d=>d.DefaultValue!.Value.Clone());var cfg=new[]{new AcquisitionImageConfig()};Set(p,"ImageConfigList",JsonSerializer.Serialize(cfg));foreach(int mode in new[]{1,2}){Set(p,"ImageSourceType",mode);var node=new NodeDocument("ui",plugin.Manifest.Id,"1.0.0","多图采集",p);var window=plugin.CreateWpfEditor(new(node,Environment.CurrentDirectory,_=>{},_=>throw new NotSupportedException()){DisplayIndex=3});window.Left=-30000;window.Top=-30000;window.ShowActivated=false;window.ShowInTaskbar=false;window.Show();window.UpdateLayout();var labels=Descendants(window).OfType<System.Windows.Controls.TextBlock>().Select(t=>t.Text).ToArray();Check(labels.Contains("图像源")&&labels.Contains("图像配置 1"),"UI common");Check(labels.Contains("相机曝光")== (mode==2),"UI camera visibility");Check(labels.Contains("取图数量")== (mode==1),"UI local visibility");var bitmap=new RenderTargetBitmap(420,500,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));string file=Path.GetFullPath($"analysis/full-audit/image-acquisition/independent-mode-{mode}.png");using(var stream=File.Create(file))encoder.Save(stream);window.Close();}}
